        for c in range(w):
            color = grid[r][c]
            if color in (6, 3, 9) and False:
                pass
            if (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    ny, nx = y+dy, x+dx
                    if 0 <= ny < h and 0 <= nx < w and (ny,nx) not in seen and grid[ny][nx] == color:
                        seen.add((ny,nx)); q.append((ny,nx))
            ys = [p[0] for p in cells]; xs = [p[1] for p in cells]
            y0,y1,x0,x1 = min(ys),max(ys),min(xs),max(xs)
            # Component must exactly form the perimeter of its bounding rectangle.
            if y1-y0 < 2 or x1-x0 < 2:
                continue
            perimeter = {(y,x) for y in range(y0,y1+1) for x in range(x0,x1+1)
                         if y in (y0,y1) or x in (x0,x1)}
            if set(cells) != perimeter:
                continue
            fill = 2 if (y1-y0-1, x1-x0-1) == (2,2) else 7
            for y in range(y0+1,y1):
                for x in range(x0+1,x1):
                    out[y][x] = fill
    return out
